#include <BLEDevice.h>
#include <BLEUtils.h>
#include <BLEBeacon.h>
#include <BLEAdvertising.h>

void setup() {
  Serial.begin(115200);
  BLEDevice::init("ESP32 Beacon");

  BLEBeacon beacon;
  beacon.setManufacturerId(0x4C00);
  beacon.setProximityUUID(BLEUUID("12345678-1234-1234-1234-123456789abc"));
  beacon.setMajor(1);
  beacon.setMinor(1);
  beacon.setSignalPower(-59);

  BLEAdvertisementData data;
  data.setFlags(0x04);
  data.setManufacturerData(beacon.getData());

  BLEAdvertising *advertising = BLEDevice::getAdvertising();
  advertising->setAdvertisementData(data);
  advertising->start();

  Serial.println("BLE beacon advertising");
}

void loop() {
  delay(1000);
